-- =============================================================================
-- 539 — LE CAHIER D'EXERCICES DE 1RE (partie 27)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 539 --niveau 1re --fichiers management.n1,management.n2,maths-techno.n1,maths-techno.n2 --suffixe 27 > supabase/contenu/539_exercices_1re_27.sql
--
-- 84 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   management.n1           21 exercices · 7 chapitres
--   management.n2           18 exercices · 6 chapitres
--   maths-techno.n1         24 exercices · 8 chapitres
--   maths-techno.n2         21 exercices · 7 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('72d687aa-c64f-580f-9ac7-dc8d77d990e4'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le tournoi de futsal du lycée","competence":"analyser-texte","situation":"Des élèves de terminale organisent un tournoi de futsal au profit du foyer du lycée. Ils ne pourraient pas le monter chacun de leur côté : il faut des personnes, de l’argent, du matériel et des outils.","documents":[{"id":"projet","type":"texte","genre":"article","titre":"Le projet des terminales","source":"Texte écrit pour l’exercice.","blocs":["Quinze élèves bénévoles de terminale se sont répartis en trois équipes de cinq : inscriptions, arbitrage et buvette.","Le tournoi dispose d’une subvention de 400 € versée par le foyer des élèves.","Les ballons et les chasubles sont prêtés par le club de sport du lycée.","Un élève a dessiné le logo du tournoi, et les équipes s’inscrivent grâce à un logiciel d’inscription en ligne."]}],"questions":[{"enonce":"Touche le mot qui désigne la ressource financière du tournoi.","aide":"Cherche l’argent reçu par le projet.","type":"zone","document":"projet","multiple":false},{"enonce":"Associe chaque élément du projet à la famille de ressources à laquelle il appartient.","aide":"Une ressource matérielle se touche ; une ressource immatérielle (marque, logo) non.","type":"association","gauche":[{"id":"g0","texte":"Quinze élèves bénévoles"},{"id":"g1","texte":"Subvention de 400 €"},{"id":"g2","texte":"Ballons et chasubles"},{"id":"g3","texte":"Logo du tournoi"},{"id":"g4","texte":"Logiciel d’inscription"}],"droite":[{"id":"d0","texte":"Ressource humaine"},{"id":"d1","texte":"Ressource technologique"},{"id":"d2","texte":"Ressource matérielle"},{"id":"d3","texte":"Ressource immatérielle"},{"id":"d4","texte":"Ressource financière"}]},{"enonce":"Combien d’élèves sont chargés des inscriptions et de l’arbitrage réunis ?","aide":"Chaque équipe compte le même nombre d’élèves : lis le premier paragraphe.","type":"nombre","unite":"élèves"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m22"]},"explication":"La **subvention** de 400 € est une ressource financière : de l’argent apporté au projet."},{"cle":{"type":"association","paires":{"g0":"d0","g4":"d1","g2":"d2","g3":"d3","g1":"d4"}},"explication":"Les personnes sont des ressources **humaines**, l’argent est **financier**, les ballons **matériels**, le logo **immatériel** et le logiciel **technologique**."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 élèves","explication":"Il y a trois équipes de cinq : 5 + 5 = **10 élèves** pour les inscriptions et l’arbitrage."}]$ex$::jsonb),
  ('72d687aa-c64f-580f-9ac7-dc8d77d990e4'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Des copains qui vendent des crêpes… et une association","competence":"analyser-document","situation":"Camille vend des crêpes seule, un dimanche, sur le marché. Avec deux amis, elle crée ensuite l’association Crêp’Amis pour tenir un stand toute l’année. Qu’est-ce qui change ?","documents":[{"id":"compar","type":"tableau","titre":"Un groupe de copains et l’association Crêp’Amis","source":"Situation imaginée pour l’exercice.","colonnes":["Élément","Groupe de copains (un dimanche)","Association Crêp’Amis"],"lignes":[["Objectif et durée","S’amuser un dimanche","Tenir un stand sur 40 marchés par an, pendant des années"],["Structure","Chacun fait ce qu’il veut","Présidente, trésorier, responsable des stocks"],["Règles","Aucune","Règlement : horaires et partage des tâches"],["Cadre juridique","Aucun","Association déclarée à la préfecture"]],"enteteLignes":true},{"id":"clients","type":"graphique","forme":"barres","titre":"Clients servis en une matinée","source":"Chiffres imaginés pour l’exercice.","categories":["Camille seule","À trois, sans organisation","À trois, avec des rôles"],"series":[{"nom":"Clients","valeurs":[15,30,45],"teinte":"violet"}],"axeY":{"titre":"Clients servis","min":0,"max":50,"pas":10},"valeurs":false}],"questions":[{"enonce":"Touche la case qui montre ce qu’il manque au groupe de copains pour exister aux yeux de la loi.","aide":"Cherche la ligne qui parle de la loi et des statuts.","type":"zone","document":"compar","multiple":false},{"enonce":"Range chaque phrase : intérêt individuel d’un membre ou intérêt collectif du groupe ?","aide":"L’intérêt collectif est celui du groupe entier, pas celui d’un seul membre.","type":"categories","categories":[{"id":"c0","texte":"Intérêt individuel"},{"id":"c1","texte":"Intérêt collectif"}],"items":[{"id":"i0","texte":"Équilibrer le budget de l’association"},{"id":"i1","texte":"Camille veut gagner un peu d’argent de poche"},{"id":"i2","texte":"Tenir le stand sur 40 marchés par an"},{"id":"i3","texte":"Un ami veut surtout rencontrer du monde"}]},{"enonce":"Touche la manière de s’organiser qui permet de servir le plus de clients.","aide":"Cherche la barre la plus haute.","type":"zone","document":"clients","multiple":false},{"enonce":"De combien de clients l’équipe organisée dépasse-t-elle Camille seule ?","aide":"Soustrais le résultat de Camille à celui de l’équipe organisée.","type":"nombre","unite":"clients"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c1"]},"explication":"Le groupe n’a **aucun cadre juridique** : il ne peut ni signer de contrat ni embaucher en son nom."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"Gagner de l’argent de poche ou rencontrer du monde sont des intérêts **individuels** ; tenir le stand et équilibrer le budget sont des intérêts **collectifs**."},{"cle":{"type":"zone","ids":["k2"]},"explication":"À trois **avec des rôles répartis**, on sert 45 clients : la spécialisation rend l’équipe plus efficace."},{"cle":{"type":"nombre","valeur":30,"tolerance":0},"affichage":"30 clients","explication":"45 − 15 = **30 clients** de plus : à trois et organisés, on sert trois fois plus de monde."}]$ex$::jsonb),
  ('72d687aa-c64f-580f-9ac7-dc8d77d990e4'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le club de robotique à l’épreuve de la coordination","competence":"analyser-document","situation":"Au lycée, le club de robotique réunit 24 élèves qui préparent un robot pour une rencontre régionale. Zoé, la présidente, raconte ce qui marche et ce qui coince.","documents":[{"id":"entretien","type":"texte","genre":"article","titre":"Entretien avec Zoé, présidente du club","source":"Entretien écrit pour l’exercice ; club imaginaire.","blocs":["« À vingt-quatre, chacun s’est spécialisé : programmation, mécanique, électronique. Seuls, nous ne finirions jamais un robot. »","« Le club est déclaré en association : il a pu ouvrir un compte en banque et signer une convention avec le lycée. Nous avons un règlement et un bureau. »","« Mais tout n’est pas simple. Nos réunions du mercredi servent surtout à coordonner les équipes : l’an dernier, les électroniciens ont commandé des capteurs que les mécaniciens ne pouvaient pas monter. Et Léo veut gagner la coupe pour briller, alors qu’Inès vient surtout pour s’amuser. »"]},{"id":"bilan","type":"tableau","titre":"Ce dont dispose le club","source":"Données imaginées pour l’exercice.","colonnes":["Élément","Quantité ou montant"],"lignes":[["Élèves qui savent programmer","8 élèves"],["Cotisations des 24 membres (10 € chacun)","240 €"],["Subvention du lycée","600 €"],["Kits de robotique","4 kits"],["Licence du logiciel de simulation","1 licence"],["Marque et logo du club","1 logo"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui désigne la principale difficulté de l’action collective dans ce club.","aide":"Quel verbe décrit le travail des réunions du mercredi ?","type":"zone","document":"entretien","multiple":false},{"enonce":"Associe chaque élément du tableau à la famille de ressources correspondante.","aide":"Un logiciel est une ressource technologique ; un logo ou une marque, une ressource immatérielle.","type":"association","gauche":[{"id":"g0","texte":"Élèves qui savent programmer"},{"id":"g1","texte":"Cotisations des membres"},{"id":"g2","texte":"Kits de robotique"},{"id":"g3","texte":"Licence du logiciel de simulation"},{"id":"g4","texte":"Marque et logo du club"}],"droite":[{"id":"d0","texte":"Ressource financière"},{"id":"d1","texte":"Ressource immatérielle"},{"id":"d2","texte":"Ressource humaine"},{"id":"d3","texte":"Ressource matérielle"},{"id":"d4","texte":"Ressource technologique"}]},{"enonce":"Quel est le montant total des ressources financières du club ?","aide":"Additionne les cotisations (déjà totalisées dans le tableau) et la subvention.","type":"nombre","unite":"€"},{"enonce":"Range ces intérêts : individuel ou collectif ?","aide":"Demande-toi : est-ce pour une personne ou pour tout le groupe ?","type":"categories","categories":[{"id":"c0","texte":"Intérêt individuel"},{"id":"c1","texte":"Intérêt collectif"}],"items":[{"id":"i0","texte":"Faire durer le club d’une année sur l’autre"},{"id":"i1","texte":"Gagner la coupe pour briller (Léo)"},{"id":"i2","texte":"S’amuser avec ses amis (Inès)"},{"id":"i3","texte":"Terminer le robot dans les délais"}]},{"enonce":"Malgré ces difficultés de coordination, pourquoi l’action collective reste-t-elle préférable ici ?","aide":"Pense à ce que Zoé dit des compétences de chacun.","type":"choix","options":[{"id":"a","texte":"Elle fait disparaître les intérêts individuels de tous les membres du club"},{"id":"b","texte":"Elle évite au club d’avoir un règlement et de coordonner les équipes"},{"id":"c","texte":"Elle dispense le club de réunir des ressources financières pour agir"},{"id":"d","texte":"Elle permet de se spécialiser et de réaliser ce qu’aucun élève ne ferait seul"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m57"]},"explication":"**Coordonner** les équipes est la limite de l’action collective : plus on est nombreux, plus il faut s’accorder."},{"cle":{"type":"association","paires":{"g1":"d0","g4":"d1","g0":"d2","g2":"d3","g3":"d4"}},"explication":"Les compétences sont **humaines**, les cotisations **financières**, les kits **matériels**, la licence **technologique**, le logo **immatériel**."},{"cle":{"type":"nombre","valeur":840,"tolerance":0},"affichage":"840 €","explication":"240 € de cotisations + 600 € de subvention = **840 €**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Léo et Inès poursuivent des buts **individuels** ; terminer le robot et durer sont des buts **collectifs**."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’action collective est plus **efficace** : on cumule des compétences et on se spécialise. Mais elle ne supprime ni les intérêts individuels ni le besoin de coordination."}]$ex$::jsonb),
  ('16ac6ae3-1505-563b-bc81-c18df8225bab'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Trois organisations dans la même ville","competence":"lire-tableau","situation":"Dans la ville imaginaire de Valmoray, Léa compare une boulangerie, la mairie et un club de rugby. Elle veut comprendre d’où vient l’argent de chacun et ce qu’il produit.","documents":[{"id":"orgas","type":"tableau","titre":"Trois organisations de Valmoray","source":"Organisations imaginées pour l’exercice.","colonnes":["Organisation","Ce qu’elle produit","D’où vient son argent"],"lignes":[["Le Fournil d’Anaïs (boulangerie)","Du pain et des viennoiseries vendus au public","Ventes aux clients"],["Mairie de Valmoray","Écoles, voirie, médiathèque","Impôts et taxes locaux"],["Club de rugby de Valmoray","Entraînements et matchs","Cotisations, dons, subventions et bénévolat"]],"enteteLignes":true},{"id":"cantine","type":"fiche","modele":"panneau","titre":"Le panneau de la cantine","entete":"Cantine municipale de Valmoray","sousTitre":"Tarifs de l’année","emoji":"🍽️","lignes":[{"texte":"Prix du repas payé par la famille","valeur":"3,00 €","id":"z1"},{"texte":"Coût de production d’un repas","valeur":"7,50 €","id":"z2"}],"pied":"Service géré par la mairie. Panneau imaginé pour l’exercice."}],"questions":[{"enonce":"Touche la case qui dit comment se finance la mairie.","aide":"Regarde la dernière colonne, ligne de la mairie.","type":"zone","document":"orgas","multiple":false},{"enonce":"Associe chaque organisation à sa famille.","aide":"Regarde la finalité et l’origine de l’argent dans le tableau.","type":"association","gauche":[{"id":"g0","texte":"Le Fournil d’Anaïs"},{"id":"g1","texte":"Mairie de Valmoray"},{"id":"g2","texte":"Club de rugby"}],"droite":[{"id":"d0","texte":"Organisation de la société civile"},{"id":"d1","texte":"Organisation publique"},{"id":"d2","texte":"Entreprise privée"}]},{"enonce":"Quelle part du coût d’un repas la famille paie-t-elle ?","aide":"Divise le prix payé par le coût de production, puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Le repas de la cantine est donc un service…","aide":"Compare le prix payé et le coût de production.","type":"choix","options":[{"id":"a","texte":"non marchand : le prix payé est très inférieur à son coût"},{"id":"b","texte":"marchand : la mairie réalise un profit sur chaque repas"},{"id":"c","texte":"marchand : un prix payé suffit à rendre un service marchand"},{"id":"d","texte":"non marchand : il est entièrement gratuit pour toutes les familles"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"La mairie se finance par les **impôts et taxes** : c’est typique d’une organisation publique."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"La boulangerie vise le profit (entreprise **privée**), la mairie l’intérêt général (organisation **publique**), le club une cause non lucrative (**société civile**)."},{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 %","explication":"3 ÷ 7,50 = 0,4, soit **40 %** du coût."},{"cle":{"type":"choix","ids":["a"]},"explication":"Un service est **non marchand** quand il est fourni à un prix très inférieur à son coût : ici 3 € contre 7,50 €."}]$ex$::jsonb),
  ('16ac6ae3-1505-563b-bc81-c18df8225bab'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La crèche associative qui facture les familles","competence":"lire-graphique","situation":"La crèche Les P’tits Loups accueille 30 enfants. Les familles paient une participation, et pourtant elle n’est pas une entreprise. Pourquoi ? Léa examine ses statuts et son budget.","documents":[{"id":"statuts","type":"fiche","modele":"affiche","titre":"Les statuts résumés","entete":"Crèche associative Les P’tits Loups","sousTitre":"Statuts résumés — texte écrit pour l’exercice","emoji":"🧸","lignes":[{"texte":"Forme juridique","valeur":"Association loi 1901"},{"texte":"But","valeur":"Accueillir 30 enfants de moins de 3 ans"},{"texte":"Bénéfices","valeur":"Jamais partagés entre les membres","id":"z1"},{"texte":"Gestion","valeur":"Conseil de parents bénévoles"}],"pied":"Crèche imaginaire."},{"id":"budget","type":"graphique","forme":"secteurs","titre":"Les ressources de la crèche (300 000 € par an)","source":"Chiffres imaginés pour l’exercice.","categories":["Participation des familles","Subvention de la commune","Subvention du département","Dons"],"series":[{"nom":"Part des ressources","valeurs":[35,30,30,5],"teinte":"turquoise"}]}],"questions":[{"enonce":"Touche la ligne des statuts qui prouve que la crèche a une finalité non lucrative.","aide":"Cherche ce qu’il advient des bénéfices.","type":"zone","document":"statuts","multiple":false},{"enonce":"Touche la ressource la plus importante de la crèche.","aide":"Cherche le plus grand secteur du graphique.","type":"zone","document":"budget","multiple":false},{"enonce":"Quelle part des ressources vient de financements publics (commune et département) ?","aide":"Additionne les deux parts publiques.","type":"nombre","unite":"%"},{"enonce":"Les familles paient une partie du service. La crèche est-elle pour autant une entreprise ?","aide":"Pour classer une organisation, regarde sa finalité plutôt que son nom.","type":"choix","options":[{"id":"a","texte":"Oui : dès qu’une organisation facture un service, c’est une entreprise"},{"id":"b","texte":"Non : une association ne peut jamais vendre de services"},{"id":"c","texte":"Oui : elle emploie des salariés comme n’importe quelle entreprise"},{"id":"d","texte":"Non : sa finalité reste non lucrative, même si elle facture un service"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Les bénéfices ne sont **jamais partagés** : la finalité est non lucrative."},{"cle":{"type":"zone","ids":["k0"]},"explication":"La **participation des familles** pèse 35 % : c’est la première ressource."},{"cle":{"type":"nombre","valeur":60,"tolerance":0},"affichage":"60 %","explication":"30 % + 30 % = **60 %** des ressources sont publiques."},{"cle":{"type":"choix","ids":["d"]},"explication":"Une association peut vendre des services : ce qui compte, c’est sa **finalité non lucrative**. Les trois autres idées sont fausses."}]$ex$::jsonb),
  ('16ac6ae3-1505-563b-bc81-c18df8225bab'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Clinique, hôpital public, fondation : qui est qui ?","competence":"analyser-document","situation":"Trois organisations soignent ou financent des soins dans la même région imaginaire. Pour les classer, on ne regarde pas leur nom mais leur finalité, ce qu’elles produisent et qui les finance.","documents":[{"id":"compar","type":"tableau","titre":"Trois organisations de santé","source":"Organisations imaginées pour l’exercice.","colonnes":["Critère","Clinique du Parc","Centre hospitalier de Bellerive","Fondation Santé Vive"],"lignes":[["Finalité","Rémunérer ses actionnaires","Servir l’intérêt général","Soutenir la recherche médicale"],["Financement","Soins facturés, capitaux d’actionnaires","Fonds publics","Dons et legs"],["Salariés","300","1 500","85"]],"enteteLignes":true},{"id":"ppp","type":"texte","genre":"article","titre":"Un nouveau bâtiment pour l’hôpital","source":"Article imaginé pour l’exercice.","blocs":["Le Centre hospitalier de Bellerive, établissement public, vient d’ouvrir un nouveau bâtiment. Il a été construit, puis sera entretenu pendant trente ans, par une entreprise privée du bâtiment dans le cadre d’un partenariat public-privé.","L’hôpital verse un loyer à l’entreprise mais reste seul responsable des soins donnés aux patients."]}],"questions":[{"enonce":"Classe ces cinq organisations dans la bonne famille.","aide":"Pose-toi trois questions : sa finalité, ce qu’elle produit, qui la finance ?","type":"categories","categories":[{"id":"c0","texte":"Entreprise privée"},{"id":"c1","texte":"Organisation publique"},{"id":"c2","texte":"Organisation de la société civile"}],"items":[{"id":"i0","texte":"Un syndicat de salariés de la santé"},{"id":"i1","texte":"Fondation Santé Vive"},{"id":"i2","texte":"Une pharmacie de quartier tenue par une pharmacienne"},{"id":"i3","texte":"Centre hospitalier de Bellerive"},{"id":"i4","texte":"Clinique du Parc"}]},{"enonce":"Touche le mot qui montre que la frontière entre secteur public et secteur privé est poreuse.","aide":"Quel mot désigne l’alliance d’un hôpital public et d’une entreprise privée ?","type":"zone","document":"ppp","multiple":false},{"enonce":"Combien de fois le Centre hospitalier compte-t-il plus de salariés que la clinique ?","aide":"Divise l’effectif de l’hôpital par celui de la clinique.","type":"nombre","unite":"fois"},{"enonce":"Malgré ce contrat avec une entreprise du bâtiment, le Centre hospitalier reste une organisation publique parce que…","aide":"Regarde ce qui n’a pas changé : la mission de l’hôpital et la façon dont il est financé.","type":"choix","options":[{"id":"a","texte":"il verse un loyer, ce qui prouve qu’il cherche à réaliser un profit"},{"id":"b","texte":"sa finalité reste l’intérêt général et ses ressources restent publiques"},{"id":"c","texte":"un partenariat avec le privé fait de l’hôpital une entreprise privée"},{"id":"d","texte":"l’entreprise du bâtiment est elle-même une organisation publique"}],"multiple":false}]}$ex$::jsonb,
