   $ex${"titre":"La piscine de la mairie de Valmoray","competence":"analyser-texte","situation":"La directrice générale des services de Valmoray explique comment la mairie gère sa piscine municipale. Un management public suit des règles propres, mais mesure lui aussi ses résultats.","documents":[{"id":"entretien","type":"texte","genre":"article","titre":"Rencontre avec la directrice générale des services","source":"Entretien imaginé pour l’exercice.","blocs":["« À la piscine de Valmoray, la continuité est la première règle : le bassin reste ouvert en août comme en janvier. »","« Deuxième règle, l’égalité : deux familles dans la même situation paient le même tarif, quel que soit leur quartier. »","« Troisième règle, l’adaptabilité : depuis cette année, on réserve son créneau sur le site de la ville plutôt que de faire la queue. »","« Nous ne cherchons pas le profit : notre budget est voté chaque année par les élus et notre mission est l’intérêt général. »"]},{"id":"indic","type":"tableau","titre":"Les indicateurs de la piscine","source":"Chiffres imaginés pour l’exercice.","colonnes":["Indicateur","Objectif","Résultat"],"lignes":[["Entrées de l’année","12 000","9 600"],["Satisfaction des usagers (sur 5)","4,0","4,2"],["Délai de réponse aux réservations (en heures)","24","36"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui nomme le principe illustré par la réservation en ligne.","aide":"Quel principe exige que le service évolue avec les besoins ?","type":"zone","document":"entretien","multiple":false},{"enonce":"Associe chaque principe du service public à une situation.","aide":"Continuité : sans interruption ; égalité : même traitement ; adaptabilité : le service change avec les besoins.","type":"association","gauche":[{"id":"g0","texte":"Continuité"},{"id":"g1","texte":"Égalité"},{"id":"g2","texte":"Adaptabilité"}],"droite":[{"id":"d0","texte":"Chaque habitant se voit appliquer la même règle de prêt à la bibliothèque"},{"id":"d1","texte":"Un guichet ouvre un soir par semaine pour les actifs"},{"id":"d2","texte":"Un bus municipal circule même les jours fériés"}]},{"enonce":"Quel est le taux de réalisation de l’objectif d’entrées de la piscine ?","aide":"Taux de réalisation = résultat ÷ objectif × 100.","type":"nombre","unite":"%"},{"enonce":"Touche les deux résultats qui n’atteignent pas leur objectif.","aide":"Attention : pour un délai, plus petit vaut mieux.","type":"zone","document":"indic","multiple":true}]}$ex$::jsonb,
