   $ex${"titre":"Croc’Express cherche ses facteurs clés de succès","competence":"analyser-document","situation":"La start-up imaginaire Croc’Express livre des repas à domicile. Son fondateur compare l’entreprise à deux concurrents pour savoir sur quoi il doit se battre.","documents":[{"id":"compar","type":"tableau","titre":"Croc’Express face à ses deux concurrents","source":"Chiffres imaginés pour l’exercice.","colonnes":["Indicateur","Croc’Express","LivrMiam","Flash Plat"],"lignes":[["Délai moyen de livraison (en minutes)","38","27","31"],["Restaurants partenaires","120","450","300"],["Note de l’application (sur 5)","3,9","4,5","4,2"]],"enteteLignes":true},{"id":"quentin","type":"texte","genre":"article","titre":"Entretien avec Quentin, fondateur","source":"Entretien écrit pour l’exercice ; entreprise fictive.","blocs":["« Nos livreurs à vélo cargo connaissent chaque rue du centre, et nous avons écrit un algorithme de tournées que nos concurrents n’ont pas su copier. »","« Pour réussir dans la livraison de repas, il faut livrer vite, proposer beaucoup de restaurants et avoir une application fiable. »"]}],"questions":[{"enonce":"Touche le mot qui désigne la compétence distinctive de la start-up.","aide":"Cherche ce que les concurrents n’ont pas réussi à copier.","type":"zone","document":"quentin","multiple":false},{"enonce":"Touche le nombre de restaurants du concurrent qui propose le plus grand choix.","aide":"Cherche le plus grand nombre dans la ligne des restaurants.","type":"zone","document":"compar","multiple":false},{"enonce":"De combien de minutes Croc’Express est-elle plus lente que LivrMiam ?","aide":"Soustrais le délai de LivrMiam à celui de Croc’Express.","type":"nombre","unite":"minutes"},{"enonce":"Associe chaque facteur clé de succès à l’indicateur qui le mesure.","aide":"Un facteur clé de succès est ce que le client attend ; un indicateur le mesure.","type":"association","gauche":[{"id":"g0","texte":"Livrer vite"},{"id":"g1","texte":"Offrir du choix"}