   $ex${"titre":"Le diagnostic des Vergers du Quercy","competence":"analyser-document","situation":"Les Vergers du Quercy, coopérative imaginaire de producteurs de pommes, préparent leur diagnostic stratégique. Leur veille de la semaine regroupe six informations venues de toutes parts.","documents":[{"id":"veille","type":"tableau","titre":"Le fil de veille de la coopérative","source":"Informations imaginées pour l’exercice.","colonnes":["Information relevée","Signalée par"],"lignes":[["Une aide régionale finance la conversion des vergers au bio","Le directeur"],["Le pouvoir d’achat des ménages recule de 2 % sur l’année","La comptable"],["Les consommateurs veulent de plus en plus manger des produits locaux","La responsable commerciale"],["Des capteurs d’humidité permettent d’arroser moins","Le technicien"],["Trois étés de sécheresse ont réduit les récoltes","Le chef de culture"],["Un décret interdit un produit de traitement utilisé jusqu’ici","La juriste"]],"enteteLignes":true},{"id":"directeur","type":"texte","genre":"article","titre":"Entretien avec le directeur","source":"Entretien écrit pour l’exercice ; coopérative fictive.","blocs":["« Notre vrai savoir-faire, c’est le tri de chaque pomme par variété et par calibre : aucune autre coopérative de la région ne le fait aussi finement. »","« Notre faiblesse : nous ne vendons pas en ligne. Pourtant, dans notre secteur, la clé du succès, c’est d’avoir des pommes régulières toute l’année. »"]}],"questions":[{"enonce":"Associe chaque information de la veille au facteur de l’environnement macro qu’elle illustre.","aide":"Politique : l’État et les aides ; légal : les lois ; écologique : le climat ; socioculturel : les modes de vie.","type":"association","gauche":[{"id":"g0","texte":"Aide régionale pour le bio"},{"id":"g1","texte":"Recul du pouvoir d’achat"},{"id":"g2","texte":"Goût croissant pour le local"},{"id":"g3","texte":"Capteurs d’humidité"},{"id":"g4","texte":"Étés de sécheresse"},{"id":"g5","texte":"Décret sur un produit de traitement"}],"droite":[{"id":"d0","texte":"Facteur technologique"},{"id":"d1","texte":"Facteur écologique"},{"id":"d2","texte":"Facteur politique"},{"id":"d3","texte":"Facteur légal"},{"id":"d4","texte":"Facteur socioculturel"},{"id":"d5","texte":"Facteur économique"}]},{"enonce":"Touche le mot qui désigne la compétence distinctive de la coopérative.","aide":"Cherche le savoir-faire que les autres coopératives n’ont pas.","type":"zone","document":"directeur","multiple":false},{"enonce":"Range chaque pratique dans le bon type de veille.","aide":"Concurrents, innovations, clients et fournisseurs, lois : à chaque type de veille son objet.","type":"categories","categories":[{"id":"c0","texte":"Concurrentielle"},{"id":"c1","texte":"Technologique"},{"id":"c2","texte":"Commerciale"},{"id":"c3","texte":"Juridique"}],"items":[{"id":"i0","texte":"Lire les brevets déposés pour des filets anti-grêle"},{"id":"i1","texte":"Noter les commandes passées chaque mois par les supermarchés"},{"id":"i2","texte":"Relever les prix affichés par deux autres coopératives"},{"id":"i3","texte":"Lire le nouveau décret sur les produits de traitement"}]},{"enonce":"Cette compétence distinctive correspond-elle à un facteur clé de succès du secteur ?","aide":"Relis ce que le directeur dit être la clé du succès dans son secteur.","type":"choix","options":[{"id":"a","texte":"Oui : parce que la coopérative a une faiblesse en ligne"},{"id":"b","texte":"Oui : le tri garantit des pommes régulières, ce que les clients attendent"},{"id":"c","texte":"Non : le tri n’a aucun lien avec ce que les clients attendent"},{"id":"d","texte":"Non : un facteur clé de succès est toujours interne à la coopérative"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g3":"d0","g4":"d1","g0":"d2","g5":"d3","g2":"d4","g1":"d5"}},"explication":"Chaque information relève d’un facteur du **diagnostic externe macro** : politique, économique, socioculturel, technologique, écologique, légal."},{"cle":{"type":"zone","ids":["m6"]},"explication":"Le **tri** fin des pommes est un savoir-faire que les concurrents ne possèdent pas : une compétence distinctive."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c0","i3":"c3"}},"explication":"Les brevets relèvent de la veille **technologique**, les prix des rivales de la **concurrentielle**, les commandes des clients de la **commerciale**, les décrets de la **juridique**."},{"cle":{"type":"choix","ids":["b"]},"explication":"La réussite tient à l’**articulation** entre compétence distinctive (le tri) et facteur clé de succès (des pommes régulières)."}]$ex$::jsonb),
