  ('6cfe1fd3-cca9-5372-aa79-de88f9722342'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quatre objectifs pour le club de handball","competence":"analyser-document","situation":"Le Handball Club de Valmoray compte 150 licenciés. Après avoir consulté joueurs, parents et mairie, sa présidente propose quatre formulations d’objectif. Un seul est vraiment SMART.","documents":[{"id":"objectifs","type":"tableau","titre":"Les quatre objectifs proposés","source":"Objectifs imaginés pour l’exercice.","colonnes":["Lettre","Objectif proposé"],"lignes":[["A","Passer de 150 à 180 licenciés"],["B","Gagner tous les matchs de la saison 2026-2027"],["C","Avoir beaucoup plus de licenciés d’ici septembre 2027"],["D","Passer de 150 à 180 licenciés d’ici septembre 2027"]],"enteteLignes":true},{"id":"presidente","type":"texte","genre":"article","titre":"Les propos de la présidente","source":"Propos écrits pour l’exercice ; club fictif.","blocs":["« Avant de choisir, j’ai réuni les joueurs, les parents et un élu de la mairie. Chacun a donné son avis. »","« Un objectif que tout le monde a aidé à fixer, c’est un objectif que tout le monde a envie d’atteindre. »"]}],"questions":[{"enonce":"Touche l’objectif qui respecte les critères SMART.","aide":"Il doit être précis, chiffré, réaliste et daté.","type":"zone","document":"objectifs","multiple":false},{"enonce":"Associe chaque objectif au critère SMART qui lui manque.","aide":"Cherche : le chiffre, la date, le réalisme.","type":"association","gauche":[{"id":"g0","texte":"Objectif A"},{"id":"g1","texte":"Objectif B"},{"id":"g2","texte":"Objectif C"},{"id":"g3","texte":"Objectif D"}],"droite":[{"id":"d0","texte":"Il n’est pas atteignable"},{"id":"d1","texte":"Il n’est pas mesurable"},{"id":"d2","texte":"Il ne manque aucun critère"},{"id":"d3","texte":"Il n’a pas de date limite"}]},{"enonce":"De combien de pour cent l’objectif D fait-il augmenter le nombre de licenciés ?","aide":"Taux d’évolution = (180 − 150) ÷ 150 × 100.","type":"nombre","unite":"%"},{"enonce":"Pourquoi la présidente a-t-elle consulté joueurs, parents et mairie avant de fixer l’objectif ?","aide":"Relis la dernière phrase de la présidente.","type":"choix","options":[{"id":"a","texte":"La loi interdit à un club de fixer seul un objectif de licenciés"},{"id":"b","texte":"Un objectif accepté par les parties prenantes a plus de chances d’être atteint"},{"id":"c","texte":"Un objectif imposé a plus de chances d’être atteint qu’un objectif discuté"},{"id":"d","texte":"Les parties prenantes sont seules à fixer les objectifs d’un club"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c1"]},"explication":"L’objectif **D** est précis (licenciés), mesurable (150 → 180), atteignable et daté (septembre 2027)."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"A n’est pas **daté**, B n’est pas **atteignable**, C n’est pas **mesurable** (« beaucoup plus »), D est complet."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 %","explication":"(180 − 150) ÷ 150 × 100 = **20 %**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Associer les parties prenantes rend l’objectif **légitime** et augmente ses chances d’être atteint."}]$ex$::jsonb),
