e globale"},{"id":"b","texte":"MeubleMalin doit arrêter toute production de meubles"},{"id":"c","texte":"Un avantage concurrentiel est acquis une fois pour toutes"},{"id":"d","texte":"Un avantage concurrentiel est éphémère : l’imitation l’use"}],"multiple":false}]}$ex$::jsonb,
