  ('91e19b49-d2a0-5503-b546-ffec5bc96ec4'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les carrés de carreaux de Lilou","competence":"lire-graphique","situation":"Lilou construit des carrés avec des carreaux de mosaïque. Elle note u(n) le nombre de carreaux d’un carré de côté n, et trace un diagramme en bâtons de la suite (u).","documents":[{"id":"carres","type":"graphique","forme":"barres","titre":"Nombre de carreaux u(n)","categories":["0","1","2","3","4","5"],"series":[{"nom":"u(n)","valeurs":[0,1,4,9,16,25],"teinte":"violet"}],"axeY":{"titre":"Carreaux","min":0,"max":25,"pas":5},"axeX":{"titre":"Côté n"},"valeurs":false,"source":"Données imaginées pour l’exercice"}],"questions":[{"enonce":"Touche le bâton du rang n = 4.","aide":"Les rangs sont écrits sous les bâtons.","type":"zone","document":"carres","multiple":false},{"enonce":"Combien de carreaux faut-il ajouter pour passer du carré de côté 3 à celui de côté 4 ?","aide":"Calcule u(4) − u(3) en lisant le diagramme.","type":"nombre"},{"enonce":"La suite est définie par u(n) = n². Combien de carreaux pour un carré de côté 10 ?","aide":"Remplace n par 10 dans la formule.","type":"nombre","unite":"carreaux"},{"enonce":"Que peut-on dire du sens de variation de la suite (u) d’après le diagramme ?","aide":"Compare chaque bâton au précédent.","type":"choix","options":[{"id":"a","texte":"Elle est croissante"},{"id":"b","texte":"Elle est décroissante"},{"id":"c","texte":"Elle est constante"},{"id":"d","texte":"On ne peut pas savoir"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k4"]},"explication":"Le bâton du rang 4 est le cinquième en partant de la gauche (le premier est le rang 0) : il vaut **16**."},{"cle":{"type":"nombre","valeur":7,"tolerance":0},"affichage":"7","explication":"u(4) − u(3) = 16 − 9 = **7** carreaux de plus."},{"cle":{"type":"nombre","valeur":100,"tolerance":0},"affichage":"100 carreaux","explication":"u(10) = 10² = **100** carreaux : avec une formule explicite, on calcule directement le rang voulu."},{"cle":{"type":"choix","ids":["a"]},"explication":"Chaque bâton est plus haut que le précédent (0 < 1 < 4 < 9 < 16 < 25) : la suite est **croissante**."}]$ex$::jsonb),
  ('91e19b49-d2a0-5503-b546-ffec5bc96ec4'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"La culture de bactéries du laboratoire","competence":"programmer","situation":"Dans un laboratoire, une culture contient 5 milliers de bactéries. Chaque heure, elles doublent, puis le technicien en prélève 3 milliers pour analyse : u(n+1) = 2u(n) − 3.","documents":[{"id":"culture","type":"tableau","titre":"Culture de bactéries (en milliers)","colonnes":["Heure n","0","1","2","3","4","5"],"lignes":[["u(n)",5,7,11,19,"?",67]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"},{"id":"algo","type":"texte","genre":"consigne","titre":"Algorithme de seuil","blocs":["n ← 0","u ← 5","tant que u ≤ 100 :","    n ← n + 1","    u ← 2 × u − 3","afficher n"]}],"questions":[{"enonce":"Touche le terme de rang 3.","aide":"Les rangs sont écrits dans la ligne du haut : 0, 1, 2, 3…","type":"zone","document":"culture","multiple":false},{"enonce":"Calcule la case manquante u(4) avec la relation de récurrence.","aide":"u(4) = 2 × u(3) − 3.","type":"nombre","unite":"milliers"},{"enonce":"Calcule u(6).","aide":"Pars de u(5) = 67 : une seule étape de plus.","type":"nombre","unite":"milliers"},{"enonce":"La suite (u) est-elle arithmétique ?","aide":"Calcule u(1) − u(0), u(2) − u(1), u(3) − u(2).","type":"choix","options":[{"id":"a","texte":"Oui : on multiplie toujours par 2"},{"id":"b","texte":"Oui : l’écart entre deux termes est toujours 2"},{"id":"c","texte":"Non : les écarts 2, 4, 8… ne sont pas constants"},{"id":"d","texte":"Non : les termes ne sont pas des entiers"}],"multiple":false},{"enonce":"Quelle valeur l’algorithme affiche-t-il à la fin ?","aide":"Calcule les termes u(5) puis u(6) et compare chacun à 100.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c4"]},"explication":"Le terme de rang 3 est **u(3) = 19**."},{"cle":{"type":"nombre","valeur":35,"tolerance":0},"affichage":"35 milliers","explication":"u(4) = 2 × 19 − 3 = 38 − 3 = **35**. Contrôle : 2 × 35 − 3 = 67 = u(5)."},{"cle":{"type":"nombre","valeur":131,"tolerance":0},"affichage":"131 milliers","explication":"u(6) = 2 × 67 − 3 = 134 − 3 = **131**."},{"cle":{"type":"choix","ids":["c"]},"explication":"7 − 5 = 2, 11 − 7 = 4, 19 − 11 = 8 : les écarts ne sont pas constants, donc la suite n’est **pas arithmétique**."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6","explication":"u(5) = 67 ≤ 100 : la boucle continue. u(6) = 131 > 100 : elle s’arrête. L’algorithme affiche **n = 6**, le premier rang où u(n) dépasse 100."}]$ex$::jsonb),
  ('91e19b49-d2a0-5503-b546-ffec5bc96ec4'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Deux chaînes vidéo : formule ou récurrence ?","competence":"modeliser","situation":"Léa et Sam suivent leur nombre d’abonnés mois après mois. Léa a donné une formule explicite, Sam une relation de récurrence. Qui finira devant ?","documents":[{"id":"modeles","type":"fiche","modele":"affiche","entete":"Deux modèles d’abonnés","sousTitre":"n = nombre de mois écoulés","emoji":"📈","lignes":[{"texte":"Léa : u(n) = 300 + 200n","valeur":"formule","id":"z1"},{"separateur":true},{"texte":"Sam : v(0) = 100 et v(n+1) = 2 × v(n)","valeur":"récurrence","id":"z2"}],"pied":"Modèles imaginés pour l’exercice","teinte":"violet"},{"id":"abonnes","type":"tableau","titre":"Abonnés relevés","colonnes":["Mois n","0","1","2","3","4","5"],"lignes":[["Léa u(n)",300,500,700,900,1100,1300],["Sam v(n)",100,200,400,800,1600,3200]],"enteteLignes":true,"source":"Relevés imaginés pour l’exercice"}],"questions":[{"enonce":"Touche le modèle défini par récurrence.","aide":"Dans une définition par récurrence, on passe d’un terme au suivant.","type":"zone","document":"modeles","multiple":false},{"enonce":"Combien d’abonnés Léa aura-t-elle au mois 10 ?","aide":"Avec une formule explicite, remplace directement n par 10.","type":"nombre"},{"enonce":"Touche la première case où Sam a plus d’abonnés que Léa.","aide":"Compare les deux lignes colonne par colonne, en partant de la gauche.","type":"zone","document":"abonnes","multiple":false},{"enonce":"Combien d’abonnés Sam aura-t-il au mois 6 ?","aide":"On avance pas à pas : v(6) = 2 × v(5).","type":"nombre"},{"enonce":"Pourquoi ne peut-on pas calculer v(10) aussi vite que u(10) ?","aide":"Compare ce qu’il faut connaître pour obtenir un terme dans chaque modèle.","type":"choix","options":[{"id":"a","texte":"Parce que v est décroissante, ce qui bloque le calcul"},{"id":"b","texte":"Il faut d’abord calculer v(1), …, v(9)"},{"id":"c","texte":"Parce que v(10) n’existe pas pour cette suite"},{"id":"d","texte":"Parce que v n’est pas une vraie suite de nombres"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Le modèle de **Sam** donne v(n+1) à partir de v(n) : c’est une récurrence."},{"cle":{"type":"nombre","valeur":2300,"tolerance":0},"affichage":"2300","explication":"u(10) = 300 + 200 × 10 = **2 300**."},{"cle":{"type":"zone","ids":["r1c5"]},"explication":"Au mois 3, Sam a 800 contre 900 pour Léa. Au mois 4 : **1 600 contre 1 100**, Sam passe devant."},{"cle":{"type":"nombre","valeur":6400,"tolerance":0},"affichage":"6400","explication":"v(6) = 2 × v(5) = 2 × 3 200 = **6 400**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Avec la récurrence, chaque terme dépend du précédent : pour v(10), il faut calculer **v(1), v(2), …, v(9)**. La formule de Léa permet de sauter directement au rang voulu."}]$ex$::jsonb),
