   $ex${"titre":"La campagne de vaccination","competence":"modeliser","situation":"Un centre de santé suit le nombre de personnes vaccinées chaque semaine (en dizaines). Pour prévoir la suite, Hugo veut ajuster le nuage de points par une droite, avec la méthode de Mayer.","documents":[{"id":"vacc","type":"tableau","titre":"Vaccinations par semaine","colonnes":["Semaine x","1","2","3","4","5","6"],"lignes":[["Vaccinés y (dizaines)",3,6,9,14,18,22]],"enteteLignes":true,"source":"Relevés imaginés pour l’exercice"}],"questions":[{"enonce":"Hugo forme un premier groupe avec les semaines 1 à 3. Touche les trois valeurs de y de ce groupe.","aide":"Les semaines 1, 2 et 3 sont les trois premières colonnes.","type":"zone","document":"vacc","multiple":true},{"enonce":"Le point moyen G1 du groupe 1 a pour abscisse 2. Quelle est son ordonnée ?","aide":"Moyenne de 3, 6 et 9.","type":"nombre"},{"enonce":"Le point moyen G2 du groupe 2 (semaines 4 à 6) a pour abscisse 5. Quelle est son ordonnée ?","aide":"Moyenne de 14, 18 et 22.","type":"nombre"},{"enonce":"Quel est le coefficient directeur de la droite (G1G2) ?","aide":"(y de G2 − y de G1) ÷ (x de G2 − x de G1).","type":"nombre"},{"enonce":"La droite a pour équation y = 4x + b. Quelle vaccination la droite prévoit-elle pour la semaine 7 (en dizaines) ?","aide":"Trouve d’abord b avec G1 : 6 = 4 × 2 + b. Puis calcule y pour x = 7.","type":"nombre","unite":"dizaines"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1","r0c2","r0c3"]},"explication":"Le groupe 1 contient les valeurs **3, 6 et 9**."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6","explication":"(3 + 6 + 9) ÷ 3 = **6** : G1(2 ; 6)."},{"cle":{"type":"nombre","valeur":18,"tolerance":0},"affichage":"18","explication":"(14 + 18 + 22) ÷ 3 = **18** : G2(5 ; 18)."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"(18 − 6) ÷ (5 − 2) = 12 ÷ 3 = **4**."},{"cle":{"type":"nombre","valeur":26,"tolerance":0},"affichage":"26 dizaines","explication":"b = 6 − 8 = −2, donc y = 4x − 2. Pour x = 7 : 28 − 2 = **26**. C’est une extrapolation : à prendre avec prudence."}]$ex$::jsonb),
  ('3750939c-e3db-539b-ab9e-210a5ef0b123'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La croissance d’une plante au laboratoire","competence":"raisonner","situation":"Clara mesure chaque semaine la hauteur d’une plante. Elle a saisi les mesures dans un tableur, qui propose un ajustement affine. Elle doit juger ce qu’il vaut.","documents":[{"id":"mesures","type":"tableau","titre":"Hauteur de la plante","colonnes":["Semaine x","1","2","3","4","5"],"lignes":[["Hauteur y (cm)",3,5,6,8,8]],"enteteLignes":true,"source":"Mesures imaginées pour l’exercice"},{"id":"tableur","type":"fiche","modele":"ticket","entete":"Sortie du tableur","sousTitre":"Moindres carrés","emoji":"📈","lignes":[{"texte":"Droite d’ajustement","valeur":"y = 1,3x + 2,1"}],"pied":"Résultat obtenu pour la série ci-dessus"}],"questions":[{"enonce":"Quelle est la hauteur moyenne ȳ des cinq mesures ?","aide":"(3 + 5 + 6 + 8 + 8) ÷ 5.","type":"nombre","unite":"cm"},{"enonce":"Le point moyen G(3 ; 6) est-il sur la droite y = 1,3x + 2,1 ?","aide":"Remplace x par 3 dans l’équation et compare avec 6.","type":"choix","options":[{"id":"a","texte":"Oui, car 1,3 × 3 + 2,1 = 6"},{"id":"b","texte":"Non, car 1,3 × 3 + 2,1 = 3,9"},{"id":"c","texte":"Non, car 1,3 × 3 + 2,1 = 6,9"},{"id":"d","texte":"On ne peut pas le savoir"}],"multiple":false},{"enonce":"À la semaine 5, de combien l’ajustement dépasse-t-il la mesure réelle ? (écart en cm, valeur positive)","aide":"Calcule 1,3 × 5 + 2,1 puis compare à 8 cm.","type":"nombre","unite":"cm"},{"enonce":"Selon la droite, quelle hauteur aurait la plante à la semaine 20 (en cm) ?","aide":"Remplace x par 20 dans y = 1,3x + 2,1.","type":"nombre","unite":"cm"},{"enonce":"Clara annonce « la plante mesurera 28,1 cm en semaine 20 ». Que lui répondre ?","aide":"Est-ce que la semaine 20 est dans l’intervalle des mesures (1 à 5) ?","type":"choix","options":[{"id":"a","texte":"C’est faux : une hauteur doit être un nombre entier de cm"},{"id":"b","texte":"Extrapolation lointaine : la tendance peut ne pas durer"},{"id":"c","texte":"C’est sûr : la droite passe par le point moyen G de la série"},{"id":"d","texte":"C’est sûr : l’ajustement est très bon sur les cinq semaines"}],"multiple":false}]}$ex$::jsonb,
